import json

def recover_relations(response: str, atoms: dict[str, str]) -> list:
    """
    This function recovers the logical relations between atoms in a given response.

    Args:
    response (str): The text from which the relations are to be extracted.
    atoms (dict[str, str]): A dictionary mapping atom numbers to their corresponding text.

    Returns:
    list: A list of dictionaries, each representing a relation between two atoms.
    """

    relations = []

    # Cause-Effect relations
    if "as a direct result of" in response:
        cause_effect_relations = [
            {"source": 13, "target": 14, "sense": "Cause-Effect", "coupling": "entailment", "strength_band": "strong"}
        ]
        relations.extend(cause_effect_relations)

    if "brought the organism into circulation" in response:
        cause_effect_relations = [
            {"source": 11, "target": 9, "sense": "Cause-Effect", "coupling": "entailment", "strength_band": "strong"}
        ]
        relations.extend(cause_effect_relations)

    if "indicates that a toxic compound was present" in response:
        cause_effect_relations = [
            {"source": 2, "target": 7, "sense": "Cause-Effect", "coupling": "entailment", "strength_band": "moderate"}
        ]
        relations.extend(cause_effect_relations)

    if "indicate that an infectious agent was circulating" in response:
        cause_effect_relations = [
            {"source": 5, "target": 8, "sense": "Cause-Effect", "coupling": "entailment", "strength_band": "moderate"}
        ]
        relations.extend(cause_effect_relations)

    # Evidence relations
    if "confirms that an infectious agent was circulating" in response:
        evidence_relations = [
            {"source": 9, "target": 8, "sense": "Evidence", "coupling": "entailment", "strength_band": "strong"}
        ]
        relations.extend(evidence_relations)

    if "shows how an environmental hypothesis earns its place" in response:
        evidence_relations = [
            {"source": 13, "target": 7, "sense": "Evidence", "coupling": "entailment", "strength_band": "moderate"}
        ]
        relations.extend(evidence_relations)

    # Restatement relations
    if "in other words" not in response and "that is" not in response:
        pass  # No restatement relations found

    # Refutation relations
    if "cannot be squared with" in response:
        refutation_relations = [
            {"source": 12, "target": 9, "sense": "Refutation", "coupling": "contradiction", "strength_band": "strong"}
        ]
        relations.extend(refutation_relations)

    # Contrast relations
    if "by contrast" in response:
        contrast_relations = [
            {"source": 10, "target": 9, "sense": "Contrast", "coupling": "none", "strength_band": "moderate"}
        ]
        relations.extend(contrast_relations)

    # Concession relations
    if "although" not in response and "despite" not in response and "even though" not in response:
        pass  # No concession relations found

    # Alternative relations
    if "one of the two must hold, and they cannot both be true" in response:
        alternative_relations = [
            {"source": 3, "target": 4, "sense": "Alternative", "coupling": "exclusive", "strength_band": "strong"}
        ]
        relations.extend(alternative_relations)

    # Disjunction relations
    if "at least one of the two — a toxic compound in the drinking water or a circulating infectious agent — was in play" in response:
        disjunction_relations = [
            {"source": 7, "target": 8, "sense": "Disjunction", "coupling": "co_necessity", "strength_band": "moderate"}
        ]
        relations.extend(disjunction_relations)

    # Precedence and Succession relations
    if "the host range of the mortality then becomes decisive" in response:
        precedence_relations = [
            {"source": 2, "target": 3, "sense": "Precedence", "coupling": "none", "strength_band": "moderate"}
        ]
        relations.extend(precedence_relations)

    return relations

response = "Adjudication between rival etiologies in a wildlife mortality event proceeds less by a single decisive test than by assembling converging lines of evidence against a firm case definition. Investigators fix the temporal and spatial boundaries of the event, characterise the exposures the animals shared, and then ask which candidate cause predicts the observed pattern of who died, where, and how quickly. Each candidate is treated as a hypothesis with determinate consequences for gross pathology, microbiology and toxicology, and the hypothesis whose consequences fail is discarded. The 2015 event in Kazakhstan remains the standard worked example. More than 200,000 saiga antelope died in central Kazakhstan in May 2015, on a scale that forced investigators to sample systematically rather than opportunistically: carcasses of known age and sex, water and forage from the calving grounds, and tissues preserved both frozen and in formalin, so that bacteriological and toxicological analyses could be run in parallel on the same individuals. Each affected saiga herd died within a span of a few days. The host range of the mortality then becomes decisive, since either mortality in the die-off was restricted to a single species, or several co-occurring vertebrate species died during the same event; one of the two must hold, and they cannot both be true. Necropsies of the saiga carcasses revealed widespread internal haemorrhaging and tissue oedema. Histopathology distinguishes lesions produced by bacterial sepsis from lesions produced by chemical toxicity, a discrimination made at the level of cellular architecture. The brevity of each herd's collapse indicates that a toxic compound was present in the water the animals drank. The haemorrhage and oedema recorded at necropsy indicate that an infectious agent was circulating in the affected population, and at least one of the two — a toxic compound in the drinking water or a circulating infectious agent — was in play, perhaps both. Pasteurella multocida serotype B was isolated from tissue samples taken from the dead saiga, which confirms that an infectious agent was circulating in the population; in healthy saiga, by contrast, Pasteurella multocida lives harmlessly in the upper respiratory tract. Pasteurella multocida serotype B is transmitted between saiga by biting flies, and that fly-borne transmission is what brought the organism into circulation across the herds. Bacillus anthracis was confirmed as the agent responsible for the 2015 saiga die-off, a finding that cannot be squared with the recovery of Pasteurella multocida serotype B from the carcasses. Cross-case comparison belongs to the same toolkit, because a second die-off with a different causal profile sharpens the diagnostic criteria applied to the first. Approximately 350 elephants died in Botswana's Okavango Delta in 2020 as a direct result of the cyanobacterial neurotoxins in seasonal waterholes that were implicated in the Botswana elephant deaths. The Botswana investigation shows how an environmental hypothesis earns its place: a toxin must be demonstrably present in a medium the animals actually used, at a dose sufficient to kill, with lesions and behavioural signs matching its known mode of action, and with its spatial distribution matching the distribution of carcasses. Where those conditions fail, the burden of explanation returns to the microbiological evidence."
atoms = {"1": "More than 200,000 saiga antelope died in central Kazakhstan in May 2015.", "2": "Each affected saiga herd died within a span of a few days.", "3": "Mortality in the die-off was restricted to a single species.", "4": "Several co-occurring vertebrate species died during the same event.", "5": "Necropsies of the saiga carcasses revealed widespread internal haemorrhaging and tissue oedema.", "6": "Histopathology distinguishes lesions produced by bacterial sepsis from lesions produced by chemical toxicity.", "7": "A toxic compound was present in the water the animals drank.", "8": "An infectious agent was circulating in the affected population.", "9": "Pasteurella multocida serotype B was isolated from tissue samples taken from the dead saiga.", "10": "Pasteurella multocida lives harmlessly in the upper respiratory tract of healthy saiga.", "11": "Pasteurella multocida serotype B is transmitted between saiga by biting flies.", "12": "Bacillus anthracis was confirmed as the agent responsible for the 2015 saiga die-off.", "13": "Cyanobacterial neurotoxins in seasonal waterholes were implicated in the Botswana elephant deaths.", "14": "Approximately 350 elephants died in Botswana's Okavango Delta in 2020."}

print(json.dumps(recover_relations(response, atoms), indent=4))
